for (const [language, templates] of Object.entries(LOCALIZED_ENGINE_DESCRIPTION_TEMPLATES)) {
  for (const [key, type] of Object.entries(LOCALIZED_ENGINE_DESCRIPTION_TYPES)) {
    const template = templates[type];
    if (!template) throw new Error(`Missing ${language} engine description template: ${type}`);
    TRANSLATIONS[language][key] = template;
  }
}

export function translate(language, key, values = {}) {
  const dictionary = TRANSLATIONS[language] || TRANSLATIONS.en;
  return (dictionary[key] || TRANSLATIONS.en[key] || key).replace(/\{\{(\w+)\}\}/g, (_, name) => values[name] ?? '');
}
